    ACCENT: "#2F4BDB",
    ACCENT_SUBTLE: "#F0F3FF",
    ACCENT_BORDER: "#C4CFFF",
    BORDER: "#E4E4DF",
    BORDER_STRONG: "#CFCFC8",
    SURFACE: "#FFFFFF",
    SUNKEN: "#F6F6F4",
    CODE_BG: "#F8F9FA",
    SUCCESS: "#1A7F4B",
    SUCCESS_BG: "#EAF5EF",
    WARNING: "#9A6700",
    ERROR: "#C62828",
