    const minutes = String(due.getMinutes()).padStart(2, "0");
    const meridiem = hours >= 12 ? "PM" : "AM";
    hours = hours % 12 || 12;
    const timeStr = `${hours}:${minutes} ${meridiem} IST`;
  
    const dateStr = dueYear === currentYear ? `${monthStr} ${day}` : `${monthStr} ${day}, ${dueYear}`;
